import React, { useRef, useEffect, useState } from 'react';
import { Star, Cpu, Shirt, Apple } from 'lucide-react';
import "./styles/Card.css";

// Product category data
const productCategories = [
  { id: 1, name: 'Electronics', icon: Cpu, description: 'The latest smartphones and laptops.', color: '#3b82f6' },
  { id: 2, name: 'Apparel & Fashion', icon: Shirt, description: 'A diverse collection of trendy clothing for all tastes.', color: '#10b981' },
  { id: 3, name: 'Fresh Produce', icon: Apple, description: 'The finest fruits and vegetables, freshly picked daily.', color: '#ef4444' },
];

// Customer review data
const customerReviews = [
  { id: 1, name: 'Ahmed', rating: 5, review: 'The electronic products are excellent and shipping is very fast.' },
  { id: 2, name: 'Fatima', rating: 4, review: 'The clothing collection is stylish, but I wished for more sizes.' },
  { id: 3, name: 'Sara', rating: 5, review: 'The fruits are fresh and delicious. My favorite store for groceries.' },
  { id: 4, name: 'Khaled', rating: 4, review: 'Great customer service; a minor issue with my order was resolved quickly.' },
  { id: 5, name: 'Mariam', rating: 5, review: 'Best place to buy phones with competitive prices and guaranteed quality.' },
  { id: 6, name: 'Ali', rating: 4, review: 'The website design is beautiful and easy to use, especially the produce section.' },
];

// Star component for customer rating
const RatingStars = ({ rating }) => {
  const stars = Array(5).fill(0).map((_, i) => (
    <Star
      key={i}
      style={{ 
        width: '1.25rem',
        height: '1.25rem',
        color: i < rating ? '#f97316' : '#d1d5db',
        fill: i < rating ? '#f97316' : 'none',
      }}
    />
  ));
  return <div style={{ display: 'flex', gap: '0.25rem' }}>{stars}</div>;
};

const AboutUs = () => {
  const carouselRef = useRef(null);
  const [scrollPosition, setScrollPosition] = useState(0);

  // Effect to handle automatic carousel scrolling
  useEffect(() => {
    const scrollInterval = setInterval(() => {
      if (carouselRef.current) {
        const { scrollWidth, clientWidth } = carouselRef.current;
        const maxScrollLeft = scrollWidth - clientWidth;

        let newScrollPosition = scrollPosition + 150;
        if (newScrollPosition >= maxScrollLeft) {
          newScrollPosition = 0;
        }

        carouselRef.current.scrollTo({
          left: newScrollPosition,
          behavior: 'smooth',
        });
        setScrollPosition(newScrollPosition);
      }
    }, 4000);

    return () => clearInterval(scrollInterval);
  }, [scrollPosition]);

  return (
    <div className="about-us-container">
      
      {/* About Us Section */}
      <section className="about-section">
        <h2>Our Story and Vision</h2>
        <p>
          Our store started with a simple idea: to provide a comprehensive shopping experience that combines <strong>quality, variety, and convenience</strong>, all on one easy-to-use platform. We believe online shopping should be an enjoyable, hassle-free experience, whether you're looking for the latest computer, an elegant dress, or fresh produce for a healthy meal. Our goal is to build a bridge of trust with our customers by offering the best products and the fastest delivery service.
        </p>

        <h3>Our Product Variety</h3>
        <div className="category-grid">
          {productCategories.map((category) => (
            <div key={category.id} className="category-card">
              <category.icon style={{ width: '2rem', height: '2rem', marginBottom: '0.5rem', color: category.color }} />
              <h4>{category.name}</h4>
              <p>{category.description}</p>
            </div>
          ))}
        </div>
      </section>

      {/* Customer Reviews Section (Carousel) */}
      <section className="reviews-section">
        <h2>What Our Customers Say?</h2>
        <hr/>
        
        {/* Carousel Container */}
        <div 
          ref={carouselRef}
          className="carousel-container"
        >
          {customerReviews.map((review) => (
            <div 
              key={review.id} 
              className="review-card"
            >
              <div className="card-header">
                <p className="name">{review.name}</p>
                <RatingStars rating={review.rating} />
              </div>
              <p>"{review.review}"</p>
            </div>
          ))}
          {/* Empty space at the end for scroll padding */}
          <div style={{ width: '5rem', flexShrink: 0 }}></div>
        </div>
      </section>
      
    </div>
  );
};

export default AboutUs;