
import "./styles/Card.css";

export default function Intro() {

    const scrollToSection = (id) => {
    const section = document.getElementById(id);
    if (section) {
      section.scrollIntoView({ behavior: "smooth" });
    }
  };
  return (
    <div className="intro-new">
      <div className="intro-content-new">
        <h1 className="intro-title-new">Discover Your New Obsession</h1>
        <h1 className="intro-text-new">
          Find exclusive, high-quality products curated for your modern
          lifestyle. Enjoy a seamless shopping experience and join our community
          of trend-setters.
        </h1>
        <button
          className="btn"
          onClick={() => scrollToSection("products")}
        >
         Shop Now
        </button>
      </div>
      <div className="intro-deco-bar"></div>
    </div>
  );
}
