import { useState, useContext } from 'react';
import InfoContext from "../../context/InfoContex";
import "../styles/Card.css";

export default function CardFruitsLegumes({ image, altText, h, info, p, quantity }) {
  const [quantityState, setQuantityState] = useState(quantity);
  const { rows, setRows } = useContext(InfoContext);

  function handleClick() {
    if (quantityState > 0) {
      setQuantityState(quantityState - 1);
    }

    const newItem = {
      id: Date.now(),
      name: h,
      category: "Fruits/Légumes",
      price: Number(p),
      info,
      image: process.env.PUBLIC_URL + image, // ← تعديل هنا
    };

    setRows([...rows, newItem]);
  }

  return (
    <div className="card">
      <img
        className="card-image"
        src={process.env.PUBLIC_URL + image} 
        alt={altText || "Image"}
      />
      <h2>{h}</h2>
      <p>{info}</p>

      <h5>
        {quantityState === 0
          ? "🚫 Rupture de stock"
          : `Quantité : ${quantityState}`}
      </h5>

      <h4>Prix : {p} DH / kg</h4>

      <button
        onClick={handleClick}
        disabled={quantityState < 1}
      >
        Ajouter
      </button>
    </div>
  );
}
