import { useState, useContext } from "react";
// import { useState, useContext } from "react";
import InfoContext from "../../context/InfoContex";
import "../styles/Card.css";

export default function CardPhonesPc({ image, altText, h, info, p, quantity }) {
  const [quantityState, setQuantityState] = useState(quantity);
  const { rows, setRows } = useContext(InfoContext);

  // const [rows, setRows] = useState([]);

  function handleClick() {
    if (quantityState > 0) {
      setQuantityState(quantityState - 1);
    }

    

    const newItem = {
      id: Date.now(),
      name: h,
      category: "Phones/PC",
      price: Number(p),
      info,
    };
    setRows([...rows, newItem]);
  }
  // console.log("New Quantity: ", quantityState);



  return (
    <div className="card">
      <img className="card-image" src={image} alt={altText || "Image"} />
      <h2>{h}</h2>
      <p>{info}</p>
      <h5>
        {quantityState === 0
          ? "!!!Out of stock 🚫"
          : `Quantity: ${quantityState}`}
      </h5>
      <h4>Price : {p} DH</h4>

      <button
        onClick={handleClick}
        disabled={quantityState === "!!!Out of stock 🚫" || quantityState < 1}
      >
        Ajouter
      </button>
    </div>
  );
}
