import React, { useState } from 'react';
import { Phone, Mail, MapPin, Clock, Send } from 'lucide-react';
import "./styles/Card.css";

const Contact = () => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    subject: '',
    message: ''
  });

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    // Handle form submission here
    console.log('Form submitted:', formData);
    alert('Thank you for your message! We will get back to you soon.');
    setFormData({ name: '', email: '', subject: '', message: '' });
  };

  const contactInfo = [
    {
      icon: Phone,
      title: 'Phone',
      details: '+1 (123) 456-7890',
      description: 'Mon to Fri 9am to 6pm'
    },
    {
      icon: Mail,
      title: 'Email',
      details: 'support@supperstore.com',
      description: 'Send us your query anytime!'
    },
    {
      icon: MapPin,
      title: 'Address',
      details: '123 Market Street',
      description: 'Commerce City, CC 12345'
    },
    {
      icon: Clock,
      title: 'Opening Hours',
      details: 'Monday - Saturday',
      description: '9:00 AM - 8:00 PM'
    }
  ];

  return (
    <div className="contact-container">
      <div className="contact-header">
        <h2>Get In Touch</h2>
        <p>We'd love to hear from you. Send us a message and we'll respond as soon as possible.</p>
      </div>

      <div className="contact-content">
        {/* Left Side - Contact Information */}
        <div className="contact-infoo">
          <h3>Contact Information</h3>
          <p className="info-description">
            Fill out the form and our team will get back to you within 24 hours. 
            Or contact us using the details below.
          </p>

          <div className="info-items">
            {contactInfo.map((item, index) => (
              <div key={index} className="info-item">
                <div className="info-icon">
                  <item.icon size={24} />
                </div>
                <div className="info-details">
                  <h4>{item.title}</h4>
                  <p className="detail-main">{item.details}</p>
                  <p className="detail-sub">{item.description}</p>
                </div>
              </div>
            ))}
          </div>

          <div className="map-placeholder">
            <div className="map-content">
              <MapPin size={32} />
              <p>Our Store Location</p>
              <span>123 Market Street, Commerce City</span>
            </div>
          </div>
        </div>

        {/* Right Side - Contact Form */}
        <div className="contact-form-container">
          <form onSubmit={handleSubmit} className="contact-form">
            <div className="form-group">
              <label htmlFor="name">Full Name *</label>
              <input
                type="text"
                id="name"
                name="name"
                value={formData.name}
                onChange={handleChange}
                required
                placeholder="Enter your full name"
              />
            </div>

            <div className="form-group">
              <label htmlFor="email">Email Address *</label>
              <input
                type="email"
                id="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                required
                placeholder="Enter your email address"
              />
            </div>

            <div className="form-group">
              <label htmlFor="subject">Subject *</label>
              <input
                type="text"
                id="subject"
                name="subject"
                value={formData.subject}
                onChange={handleChange}
                required
                placeholder="What is this regarding?"
              />
            </div>

            <div className="form-group">
              <label htmlFor="message">Message *</label>
              <textarea
                id="message"
                name="message"
                value={formData.message}
                onChange={handleChange}
                required
                rows="5"
                placeholder="Tell us how we can help you..."
              ></textarea>
            </div>

            <button type="submit" className="submit-button">
              <Send size={18} />
              Send Message
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Contact;