// import { Button } from 'react-native';
import { useState, useContext, useMemo, useEffect } from "react";
import InfoContext from "../../context/InfoContex";
import "../styles/Card.css";

// Move this outside the component since it doesn't change
const availableColorsMap = {
  S: ["Black", "White"],
  M: ["Black", "White", "Blue", "Gray"],
  L: ["Black", "Blue", "Gray"],
  XL: ["White", "Red", "Black"],
  38: ["White", "Black"],
  39: ["Red", "Black", "Grey"],
  40: ["White", "Black", "Beige", "Grey"],
  41: ["White", "Blue", "Black", "Beige", "Grey"],
  42: ["White", "Beige", "Black", "Grey"],
  43: ["White", "Black", "Beige"],
};

export default function CardClothes({
  name,
  category,
  price,
  quantity,
  colors,
  image,
  altText,
  info,
  size,
}) {
  const [quantityState, setQuantityState] = useState(quantity);
  const { rows, setRows } = useContext(InfoContext);
  const [selectedSize, setSelectedSize] = useState(size[0]);
  const [selectedColor, setSelectedColor] = useState(colors[0]);

  // Memoize colorsForSelectedSize to prevent unnecessary recalculations
  const colorsForSelectedSize = useMemo(
    () => availableColorsMap[selectedSize] || [],
    [selectedSize]
  );

  const filteredAvailableColors = useMemo(() => {
    return colors.filter((color) =>
      colorsForSelectedSize.some(
        (ac) => ac.toLowerCase() === color.toLowerCase()
      )
    );
  }, [colorsForSelectedSize, colors]);

  // Button is disabled if out of stock OR if no valid color is currently selected
  const isButtonDisabled = quantityState === 0 || !selectedColor;

  // Fixed useEffect with proper dependencies
  useEffect(() => {
    if (filteredAvailableColors.length > 0) {
      // Check if the current selected color is in the new list of available colors.
      const isCurrentColorValid = filteredAvailableColors.some(
        (color) => color.toLowerCase() === selectedColor?.toLowerCase()
      );

      if (!isCurrentColorValid) {
        // If the color is invalid or null, default to the first available color.
        setSelectedColor(filteredAvailableColors[0]);
      }
    } else {
      // If no colors are available for the selected size, set color to null.
      setSelectedColor(null);
    }
  }, [selectedSize, filteredAvailableColors, selectedColor, setSelectedColor]);

  function handleClick() {
    if (!isButtonDisabled) {
      setQuantityState(quantityState - 1);

      const newItem = {
        id: Date.now(),
        name,
        category,
        price,
        selectedSize,
        selectedColor,
        quantity: 1,
      };
      setRows([...rows, newItem]);
    }
  }

  return (
    <div className="card">
      <img className="card-image" src={image} alt={altText || "Image"} />
      <h2>{name}</h2>
      <p>
        {category}: {info}
      </p>

      <h4>
        {quantityState === 0
          ? "!!!Out of stock 🚫"
          : `Quantity: ${quantityState}`}
      </h4>

      <div className="sizes">
        {size.map((s) => (
          <label key={s} style={{ marginRight: "10px" }}>
            <input
              type="radio"
              name={`size-${name}`}
              value={s}
              checked={selectedSize === s}
              onChange={() => setSelectedSize(s)}
            />
            <span>{s}</span>
          </label>
        ))}
      </div>

      <div className="Color-Desponible">
        <h3>Color:</h3>
        {filteredAvailableColors.length > 0 ? (
          filteredAvailableColors.map((color) => (
            <label key={color} style={{ marginRight: "10px" }}>
              <input
                type="radio"
                name={`color-${name}`}
                value={color}
                checked={selectedColor?.toLowerCase() === color.toLowerCase()}
                onChange={() => setSelectedColor(color)}
              />
              <span
                style={{
                  backgroundColor: color.toLowerCase(),
                  display: "inline-block",
                  width: "20px",
                  height: "20px",
                  borderRadius: "50%",
                  border: "1px solid #ccc",
                  verticalAlign: "middle",
                }}
              ></span>
            </label>
          ))
        ) : (
          <p style={{ color: "red", fontSize: "14px", margin: "5px 0" }}>
            No colors available for size {selectedSize} 🙁
          </p>
        )}
      </div>

      {!selectedColor && (
        <p style={{ color: "red", fontSize: "14px", margin: "5px 0" }}>
          ❌ No color is available for size {selectedSize}.
        </p>
      )}

      <h4>Price : {price} DH</h4>

      <button onClick={handleClick} disabled={isButtonDisabled}>
        {isButtonDisabled ? "Cannot Add" : "Ajouter"}
      </button>
    </div>
  );
}
