import { useContext } from 'react';
// import { useContext } from "react";
import InfoContext from "../context/InfoContex";
import { jsPDF } from "jspdf";
import "./styles/PaymentPage.css";

export default function PaymentPage() {
  const { rows, setRows } = useContext(InfoContext);

  function handleDelete(itemId) {
    const updatedRows = rows.filter((item) => item.id !== itemId);
    setRows(updatedRows);
  }

  const totalPrice = rows.reduce(
    (acc, row) => acc + (Number(row.price) || 0),
    0
  );

  function handleDownloadPDF() {
    if (rows.length === 0) return;

    const doc = new jsPDF();
    doc.setFontSize(18);
    doc.text("Payment Ticket", 20, 20);

    doc.setFontSize(12);
    rows.forEach((row, index) => {
      doc.text(
        `${index + 1}. ${row.name} (${row.category}) - ${row.price} DH`,
        20,
        30 + index * 10
      );
    });

    doc.text(`Total: ${totalPrice} DH`, 20, 40 + rows.length * 10);
    doc.text("Thank you for your purchase!", 20, 50 + rows.length * 10);

    doc.save("payment_ticket.pdf");
  }

  return (
    <div className="payment-page">
      <div className="payment-container">
        <div className="order-summary">
          <h2>Order Summary</h2>
          {rows.length === 0 ? (
            <p>Your cart is empty 🛒</p>
          ) : (
            <ul>
              {rows.map((row) => (
                <li key={row.id}>
                  <span>{row.name} ({row.category})</span>
                  <span>{row.price} DH</span>
                  <button
                    className="delete-button"
                    onClick={() => handleDelete(row.id)}
                  >
                    Delete
                  </button>
                </li>
              ))}
            </ul>
          )}
          <div className="total-container" style={{ marginTop: "10px", display: "flex", alignItems: "center", gap: "10px" }}>
            <hr />
            <strong>Total:</strong> {totalPrice} DH
            {rows.length > 0 && (
              <button
                onClick={handleDownloadPDF}
                style={{
                  padding: "8px 16px",
                  backgroundColor: "#4CAF50",
                  color: "white",
                  border: "none",
                  borderRadius: "5px",
                  cursor: "pointer",
                  fontWeight: "bold",
                  transition: "0.3s",
                }}
                onMouseOver={(e) => e.currentTarget.style.backgroundColor = "#45a049"}
                onMouseOut={(e) => e.currentTarget.style.backgroundColor = "#4CAF50"}
              >
                Download PDF Ticket
              </button>
            )}
          </div>
        </div>

        <div className="payment-form">
          <h2>Payment Details</h2>
          <form>
            <label>
              Name on Card
              <input type="text" placeholder="John Doe" required />
            </label>
            <label>
              Card Number
              <input type="text" placeholder="1234 5678 9012 3456" required />
            </label>
            <label>
              Expiry Date
              <input type="text" placeholder="MM/YY" required />
            </label>
            <label>
              CVV
              <input type="password" placeholder="123" required />
            </label>
            <button type="submit" disabled={rows.length === 0}>
              Pay {totalPrice} DH
            </button>
          </form>
        </div>
      </div>
    </div>
  );
}
